insert into eg_margin_contract_balance_temp ( contract_code, org_id, client_code,bill_contract_code, business_code, contract_name , lease_date_start , lease_date_end , business_name , currency_type , client_name, supplier_margin_balance, payable_margin_balance, other_margin_balance, lessee_margin_balance ) select t.contract_code, t.org_id, case when t.client_code is null then '0' else t.client_code end as client_code, case when t.bill_contract_code is null then '0' else t.bill_contract_code end as bill_contract_code, case when ec.business_code is null then 'ZLYW' else ec.business_code end as business_code, ec.contract_name , ec.lease_date_start , ec.lease_date_end , ec.business_name , ec.currency_type , '' as client_name, coalesce(t.supplier_margin_balance, 0) as supplier_margin_balance, coalesce(t.payable_margin_balance, 0) as payable_margin_balance, coalesce(t.other_margin_balance, 0) as other_margin_balance, coalesce(t.lessee_margin_balance, 0) as lessee_margin_balance from ( select a.contract_code, a.org_id,a.client_code,a.bill_contract_code,sum(coalesce(a.supplier_margin_balance, 0)) as supplier_margin_balance, sum(coalesce(a.payable_margin_balance, 0)) as payable_margin_balance, sum(coalesce(a.other_margin_balance, 0)) as other_margin_balance, sum(coalesce(a.lessee_margin_balance, 0)) as lessee_margin_balance from ( select * from eg_contract_balance_month where 1 = 1 and (supplier_margin_balance != 0 or payable_margin_balance != 0 or other_margin_balance != 0 or lessee_margin_balance != 0) and period_code = #{param.lastPeriodCode} and org_id in ('01-C0001','02-C0001','30001','80001')
and org_id = #{param.orgId}
and org_id in
#{item}
and business_code in
#{item}
order by contract_code, org_id,client_code, bill_contract_code ) a where 1 = 1 group by a.contract_code, a.org_id,a.client_code, a.bill_contract_code) t left join (select org_id, contract_code, max(business_code) business_code, max(contract_name) contract_name, min(lease_date_start) lease_date_start, max(lease_date_end) lease_date_end, max(business_name) business_name, max(currency_type) currency_type from eg_contract_month group by org_id, contract_code) ec on ec.contract_code = t.contract_code and ec.org_id = t.org_id where 1 = 1 and (t.supplier_margin_balance != 0 or t.payable_margin_balance != 0 or t.other_margin_balance != 0 or t.lessee_margin_balance != 0)

insert into eg_margin_contract_balance_temp ( contract_code, org_id, client_code, bill_contract_code, business_code, contract_name , lease_date_start , lease_date_end , business_name , currency_type , client_name, supplier_margin_balance, payable_margin_balance, other_margin_balance, lessee_margin_balance ) select distinct on(t.contract_code, t.org_id,t.client_code,t.bill_contract_code) t.contract_code, t.org_id, case when t.client_code is null then '0' else t.client_code end as client_code, case when t.bill_contract_code is null then '0' else t.bill_contract_code end as bill_contract_code, case when ec.business_code is null then 'ZLYW' else ec.business_code end as business_code, ec.contract_name , ec.lease_date_start , ec.lease_date_end , ec.business_name , ec.currency_type , '' as client_name, t.supplier_margin_balance, t.payable_margin_balance, t.other_margin_balance, t.lessee_margin_balance from ( select a.contract_code, a.org_id, a.client_code, a.bill_contract_code, sum(coalesce(a.supplier_margin_balance,0)) as supplier_margin_balance, sum(coalesce(a.payable_margin_balance,0)) as payable_margin_balance, sum(coalesce(a.other_margin_balance,0)) as other_margin_balance, sum(coalesce(a.lessee_margin_balance,0)) as lessee_margin_balance from () a inner join ( select contract_code, org_id, client_code, bill_contract_code, max(id) id from eg_contract_balance where period_code = #{param.periodCode} and org_id in ('01-C0001','02-C0001','30001','80001')
and org_id = #{param.orgId}
and org_id in
#{item}
and business_code in
#{item}
and del_flag = '0' and contract_code is not null and org_id is not null group by contract_code, org_id, client_code, bill_contract_code ) b on a.id = b.id where 1=1 group by a.contract_code, a.org_id, a.client_code, a.bill_contract_code ) t left join (select org_id, contract_code, max(business_code) business_code, max(contract_name) contract_name, min(lease_date_start) lease_date_start, max(lease_date_end) lease_date_end, max(business_name) business_name, max(currency_type) currency_type from eg_contract_month group by org_id, contract_code) ec on t.contract_code = ec.contract_code and ec.org_id = t.org_id where 1=1 on conflict (contract_code, org_id,client_code,bill_contract_code) do update set supplier_margin_balance = excluded.supplier_margin_balance, lessee_margin_balance = excluded.lessee_margin_balance, payable_margin_balance = excluded.payable_margin_balance, other_margin_balance =excluded.other_margin_balance

